def run_backfill(db: Session = Depends(get_db)) -> dict[str, object]:
    """Fill the queue from sources an earlier release stored without promoting them.

    Deliberately an explicit request rather than a startup hook. What the backfill
    reads is the queue's history, not a durable record of what was promoted, and the
    one read it can make is undone by hand: an owner who dismisses every promoted
    item leaves a queue that looks untouched again. Asking for it makes that the
    owner's decision, once, instead of something a restart does to them silently.
    """
